## 기타

If the order is undefined or null then push them to last

Sample: 

```js
const columns = [
    {name: 'test 1'}, // Order will be 21 after sorting
    {name: 'test 2'}, // Order will be 22 after sorting
    {name: 'test 3'}, // Order will be 23 after sorting
    {order: 15},
    {}, // Order will be 24 after sorting
    {order: 20},
    {order: -4},
    {order: -7},
    {}, // Order will be 25 after sorting
];
//console.log('columns', columns);

const orders = columns.map(column => {
    //console.log('column', column.order);
    //console.log('typeof column', typeof column.order);
    //console.log('column.order || -1', column.order || -1)
    return (typeof column.order === 'undefined' || column.order === null) ? -1 : column.order;
});

//console.log('orders', orders);
let max = Math.max(...orders);
//console.log('max', max);

columns.sort(function(a, b){
    if (a.order && b.order) {
        return a.order - b.order;
    }
    if (typeof b.order === 'undefined' || b.order === null) {
        b.order = ++max;
    }
    if (typeof a.order === 'undefined' || a.order === null) {
        a.order = ++max;
    }
    return a.order - b.order;
});

console.log('columns', columns);


/**
 * Result:
 * columns [
 *   { order: -7 },
 *   { order: -4 },
 *   { order: 15 },
 *   { order: 20 },
 *   { name: 'test 1', order: 21 },
 *   { name: 'test 2', order: 22 },
 *   { name: 'test 3', order: 23 },
 *   { order: 24 },
 *   { order: 25 }
 * ]
 */
```

Automation of @trezor/connect release process

## Description

@trezor/connect v9 is still beta. The last thing I need to resolve before going public is release process automation. But I need to create a new job bypassing regular checks that are used for other packages since I want to do 2 things: 1 test release process as if it was already public. 2 keep npm package still in beta.

This PR adds `demandRankDisplayText` to the artwork price insights



### Example
- Query 
```graphql
query {
  artwork(id: "artwork-id") {
    artistNames
    title
    marketPriceInsights {
      demandRank
      demandRankDisplayText
    }
  }
}
```

- Result
```json
{
  "data": {
    "artwork": {
      "artistNames": "FamousArtist",
      "title": "CoolWork",
      "marketPriceInsights": {
        "demandRank": 0.877,
        "demandRankDisplayText": "Active Demand"
      }
    }
  }
}
```

